import pandas as pd
import numpy as np

def main():
    print("Starting SPO Financial Evaluation (Exact Framework Match)...")

    # ---------------------------------------------------------
    # 1. Load Data
    # ---------------------------------------------------------
    # The plan generated by the SPO algorithm
    plan_file = 'last_3_months_demand_forecast_SPO.csv'
    # The ground truth environment data
    env_file = 'rl_ready_sales_data.csv'

    print(f"Loading Plan: {plan_file}")
    print(f"Loading Environment: {env_file}")
    
    spo_df = pd.read_csv(plan_file)
    env_df = pd.read_csv(env_file)

    # Convert dates
    spo_df['Date'] = pd.to_datetime(spo_df['Date'])
    env_df['Date'] = pd.to_datetime(env_df['Date'])

    # Ensure column name consistency for the merge
    if 'Q' in spo_df.columns:
        spo_df = spo_df.rename(columns={'Q': 'SPO_Order_Qty'})
    
    # ---------------------------------------------------------
    # 2. Merge & Simulation (Needed to generate cost columns)
    # ---------------------------------------------------------
    print("Merging and Simulating Inventory Dynamics...")
    
    # Merge Plan with Environment (Test set only)
    merged_df = pd.merge(
        env_df,
        spo_df[['Date', 'Store ID', 'Product ID', 'SPO_Order_Qty']],
        on=['Date', 'Store ID', 'Product ID'],
        how='inner' # Intersection (Test Set)
    )
    
    merged_df = merged_df.sort_values(['Store ID', 'Product ID', 'Date'])
    
    # Container for daily simulation results
    daily_records = []

    # Iterate through each SKU to simulate inventory logic
    skus = merged_df[['Store ID', 'Product ID']].drop_duplicates().values
    
    for store_id, prod_id in skus:
        sku_data = merged_df[(merged_df['Store ID'] == store_id) & 
                             (merged_df['Product ID'] == prod_id)].copy()
        
        if sku_data.empty: continue

        # --- SKU Parameters ---
        first_row = sku_data.iloc[0]
        
        # Costs
        unit_cost = first_row['Unit_Cost']
        holding_cost_daily = first_row['Holding_Cost_Daily']
        order_cost_fixed = first_row['Order_Cost_Fixed']
        stockout_penalty = first_row['Stockout_Penalty']
        lead_time = int(first_row['Lead_Time'])
        
        # Selling Price (Median to handle fluctuations)
        selling_price = sku_data['Price'].median()

        # Initial State
        # Heuristic: Start with enough inventory to cover lead time to be fair
        avg_sales = sku_data['Units Sold'].mean()
        curr_inv = avg_sales * (lead_time + 1) 
        pipeline = [] # List of (days_remaining, qty)

        # --- Day-by-Day Simulation ---
        for idx, row in sku_data.iterrows():
            date = row['Date']
            
            # 1. Receiving (Pipeline Update)
            arriving_qty = 0
            new_pipeline = []
            for days_left, qty in pipeline:
                if days_left <= 1:
                    arriving_qty += qty
                else:
                    new_pipeline.append((days_left - 1, qty))
            pipeline = new_pipeline
            
            curr_inv += arriving_qty
            
            # 2. Order Decision (From SPO Plan)
            order_qty = max(0, int(round(row['SPO_Order_Qty'])))
            if order_qty > 0:
                pipeline.append((lead_time, order_qty))
            
            # 3. Demand Realization (Using 'Units Sold' as Truth)
            actual_demand = row['Demand']
            
            # 4. Fulfillment
            sold_qty = min(curr_inv, actual_demand)
            missed_qty = actual_demand - sold_qty
            curr_inv -= sold_qty
            
            # 5. Financial Calculations (Daily)
            revenue = sold_qty * selling_price
            cogs = sold_qty * unit_cost
            
            # Cash Outflows
            cash_purchase = order_qty * unit_cost
            opex_holding = curr_inv * holding_cost_daily
            opex_order = order_cost_fixed if order_qty > 0 else 0
            cost_stockout = missed_qty * stockout_penalty
            
            # Cash Flow Net Profit
            # Profit = Revenue - (Purchase + Holding + Fixed Order + Stockout Penalty)
            total_cost_flow = cash_purchase + opex_holding + opex_order + cost_stockout
            daily_net_profit = revenue - total_cost_flow
            
            # Record Data
            daily_records.append({
                'Date': date,
                'Store ID': store_id,
                'Product ID': prod_id,
                'Actual_Demand': actual_demand, # Critical for your summary
                'Sales_Qty': sold_qty,
                'Revenue': revenue,
                'COGS': cogs,
                'Cash_Purchase': cash_purchase,
                'OpEx_Holding': opex_holding,
                'OpEx_Order': opex_order,
                'Cost_Stockout': cost_stockout,
                'Daily_Net_Profit': daily_net_profit,
                'Inventory_Level': curr_inv
            })

    # Create the simulation DataFrame
    spo_sim_df = pd.DataFrame(daily_records)
    
    # ---------------------------------------------------------
    # 3. Financial Aggregation (YOUR EXACT FRAMEWORK)
    # ---------------------------------------------------------
    print("Calculating Financial KPI Summary...")
    
    # Using 'spo_sim_df' instead of 'ww_df', but logic is identical
    spo_summary = spo_sim_df.groupby(['Store ID', 'Product ID']).agg(
        Total_Days=('Date', 'count'),
        Total_Demand=('Actual_Demand', 'sum'), # 用真实需求汇总
        Total_Sales=('Sales_Qty', 'sum'),
        Total_Revenue=('Revenue', 'sum'),
        Total_COGS=('COGS', 'sum'),
        Total_Purchase_Spend=('Cash_Purchase', 'sum'),
        Total_Holding_Cost=('OpEx_Holding', 'sum'),
        Total_Order_Fixed_Cost=('OpEx_Order', 'sum'),
        Total_Stockout_Penalty=('Cost_Stockout', 'sum'),
        Total_Net_Profit=('Daily_Net_Profit', 'sum'),
        Avg_Inventory=('Inventory_Level', 'mean')
    ).reset_index()
    
    # 计算 KPI
    spo_summary['Gross_Profit'] = spo_summary['Total_Revenue'] - spo_summary['Total_COGS']
    spo_summary['Gross_Margin_%'] = (spo_summary['Gross_Profit'] / spo_summary['Total_Revenue'].replace(0, 1)) * 100
    
    total_invest = spo_summary['Total_Purchase_Spend'] + spo_summary['Total_Holding_Cost'] + spo_summary['Total_Order_Fixed_Cost']
    spo_summary['ROI_%'] = (spo_summary['Total_Net_Profit'] / total_invest.replace(0, 1)) * 100
    
    spo_summary['Service_Level_%'] = (spo_summary['Total_Sales'] / spo_summary['Total_Demand'].replace(0, 1)) * 100
    
    # 格式化
    cols_round = ['Gross_Margin_%', 'ROI_%', 'Service_Level_%', 'Total_Revenue', 'Total_Net_Profit']
    spo_summary[cols_round] = spo_summary[cols_round].round(2)
    
    # 保存
    spo_sim_df.to_csv("spo_algorithm_daily_simulation.csv", index=False)
    spo_summary.to_csv("spo_financial_performance_summary.csv", index=False)
    
    print("-" * 30)
    print("SPO 算法评估完成 (基于真实需求)！")
    print(f"结果文件: spo_financial_performance_summary.csv")
    print("-" * 30)
    print(spo_summary[['Store ID', 'Product ID', 'Total_Demand', 'Total_Net_Profit', 'ROI_%', 'Service_Level_%']].head())

if __name__ == "__main__":
    main()